const eventoAtualId = $('Selecionar Agendamento Mais Recente (Remarcar)').item.json.event_id;

const conflitos = $input.all().filter(item => item.json.id && item.json.id !== eventoAtualId);

return [{ json: { available: conflitos.length === 0 } }];

const nome = $('Normalizar Dados da Mensagem').item.json.nome || '';

const diasSemana = ['domingo', 'segunda-feira', 'terça-feira', 'quarta-feira', 'quinta-feira', 'sexta-feira', 'sábado'];
const meses = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];

const formatarDataHora = (iso) => {
  const dt = DateTime.fromISO(iso, { zone: 'America/Sao_Paulo' });
  if (!dt.isValid) return iso;
  const dia = diasSemana[dt.weekday % 7];
  const mes = meses[dt.month - 1];
  const hora = dt.minute === 0 ? `${dt.toFormat('H')}h` : `${dt.toFormat('H')}h${dt.toFormat('mm')}`;
  return `${dia}, dia ${dt.day} de ${mes}, às ${hora}`;
};

const ativos = $input.all()
  .map(i => i.json)
  .filter(row => row.status === 'agendado' || row.status === 'remarcado')
  .filter(row => row.data)
  .sort((a, b) => new Date(a.data) - new Date(b.data));

let mensagem_consulta;

if (ativos.length === 0) {
  const opcoes = [
    `Não encontrei nenhum agendamento ativo no momento` + (nome ? `, ${nome}` : '') + `. Quer marcar um horário?`,
    (nome ? `${nome}, não` : `Não`) + ` achei nenhum horário marcado aqui pra você agora. Vamos agendar um?`
  ];
  mensagem_consulta = opcoes[Math.floor(Math.random() * opcoes.length)];
} else if (ativos.length === 1) {
  const a = ativos[0];
  const opcoes = [
    `Tem sim` + (nome ? `, ${nome}` : '') + `! Seu ${a.servico || 'horário'} está marcado para ${formatarDataHora(a.data)}.`,
    `Confirmado aqui` + (nome ? `, ${nome}` : '') + `: ${a.servico || 'seu horário'} ${formatarDataHora(a.data)}.`
  ];
  mensagem_consulta = opcoes[Math.floor(Math.random() * opcoes.length)];
} else {
  const itens = ativos.map(a => `- ${a.servico || 'horário'} em ${formatarDataHora(a.data)}`).join('\n');
  mensagem_consulta = `Você tem ${ativos.length} agendamentos ativos` + (nome ? `, ${nome}` : '') + `:\n${itens}`;
}

return [{ json: { mensagem_consulta } }];
